{
  "per_column": [
    {
      "name": "incident_category",
      "analytical_usefulness": 0.9,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "A cleaner semantic categorisation derived from short_description; directly one of the two grouping axes the query requires. Values match source text well (WiFi->network, VPN->vpn, database->database)."
    },
    {
      "name": "affected_system",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Finer-grained system extraction gives an additional grouping axis beyond category; values are sound readings of the description text (wifi_internet, database_connectivity, hardware_printer)."
    },
    {
      "name": "incident_symptom_type",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Symptom taxonomy (connectivity_failure, access_denied, outage) is a genuine new axis to compare resolution duration on. Extractions align with text; NULL/Unknown for silent rows like 'Printing issues' is acceptable."
    },
    {
      "name": "scope_indicator",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.6,
      "hallucination_observed": true,
      "rationale": "Scope (individual vs system_wide vs location_specific) is analytically useful for duration analysis. However groundedness is weaker: many descriptions ('Unable to connect to office VPN') do not clearly indicate individual vs system-wide, so some values are inferred beyond what the text supports."
    },
    {
      "name": "resolver_match",
      "analytical_usefulness": 0.4,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Appears to compare assigned_to vs closed_by; derivable from original columns but only loosely relevant to how duration varies by category and priority. Modest analytical leverage for THIS query."
    },
    {
      "name": "opened_hour_bucket",
      "analytical_usefulness": 0.6,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "Cleanly derived from opened_at timestamp. Not one of the query's two axes, but time-of-open can plausibly correlate with resolution duration, giving some analytical value."
    },
    {
      "name": "is_repeat_issue",
      "analytical_usefulness": 0.5,
      "source_groundedness": 0.35,
      "hallucination_observed": true,
      "rationale": "Repeat-issue flag could be useful, but with 375 'true' it is skewed and the source samples give no clear signal that a given incident recurs (e.g. first VPN row False, later identical VPN row True). Values appear largely unsupported/invented from single-row text."
    },
    {
      "name": "caller_type",
      "analytical_usefulness": 0.45,
      "source_groundedness": 0.7,
      "hallucination_observed": false,
      "rationale": "named_employee vs itil_user is derivable from caller_id patterns and offers a minor secondary segmentation, but is only weakly tied to the category/priority-by-duration query."
    }
  ],
  "analytical_usefulness": 0.68,
  "source_groundedness": 0.76,
  "rationale": "The set includes strong, well-grounded axes directly serving the query (incident_category, affected_system, incident_symptom_type) that let duration be grouped and compared on richer semantic dimensions than the raw category column. Several auxiliary columns (opened_hour_bucket, scope_indicator, caller_type) add moderate leverage. Groundedness is generally good with faithful extractions from short_description and timestamp fields, but scope_indicator and especially is_repeat_issue assert distinctions the single-row source text does not clearly support, indicating some inference beyond evidence."
}
